        From b7487178cb629048fcef8dbbede24e8f9453195c Mon Sep 17 00:00:00 2001
From: m-x-d <j.maxed@gmail.com>
Date: Mon, 20 May 2019 04:17:28 +0300
Subject: [PATCH] FS_NextPath(): changed logic to prevent returning gamedir
 twice because of search order changes in 7cfca78. FS_AddGameDirectory():
 fixed a bug introduced in 7cfca78.

---
 qcommon/files.c | 11 ++++-------
 1 file changed, 4 insertions(+), 7 deletions(-)

diff --git a/qcommon/files.c b/qcommon/files.c
index 69b3d3f..96cebab 100644
--- a/qcommon/files.c
+++ b/qcommon/files.c
@@ -1138,7 +1138,7 @@ static void FS_AddGameDirectory(const char *dir)
 		int numfiles;
 		char **filenames = FS_ListFiles(findname, &numfiles, 0, 0);
 		if (filenames == NULL)
-			return;
+			continue;

 		// Add the ones, which don't match pakX naming sceme
 		for (int i = 0; i < numfiles; i++)
@@ -1183,18 +1183,15 @@ static void FS_AddGameDirectory(const char *dir)
 }

 // Allows enumerating all of the directories in the search path
-char *FS_NextPath(const char *prevPath)
+char *FS_NextPath(const char *prevpath)
 {
-	if (!prevPath)
-		return fs_gamedir;
-
-	char *prev = fs_gamedir;
+	char *prev = NULL;
 	for (fsSearchPath_t *search = fs_searchPaths; search; search = search->next)
 	{
 		if (search->pack)
 			continue;

-		if (prevPath == prev)
+		if (prevpath == prev)
 			return search->path;

 		prev = search->path;
-- 
